mapper.select:
SELECT g.* FROM intangible_goods g LEFT JOIN ( SELECT oi.goods_id, COUNT(*) AS sale_count FROM goods_order_item oi INNER JOIN goods_order o ON o.id = oi.order_id WHERE oi.is_deleted = 0 AND o.is_deleted = 0 AND o.order_status NOT IN (4, 5) GROUP BY oi.goods_id ) o ON o.goods_id = g.id WHERE g.is_deleted = 0 AND g.status = 1
AND g.category_id = #{categoryId}
AND (g.goods_name LIKE CONCAT('%', #{keyword}, '%') OR g.goods_desc LIKE CONCAT('%', #{keyword}, '%')
OR g.category_id IN
#{cid}
)
ORDER BY IFNULL(o.sale_count, 0) DESC, g.create_time DESC, g.id DESC
ORDER BY g.create_time DESC, g.id DESC

SELECT g.*
FROM intangible_goods g
WHERE g.is_deleted = 0
  AND g.status = 1

    AND g.category_id = #{categoryId}


    AND (g.goods_name LIKE CONCAT('%', #{keyword}, '%')
        OR g.goods_desc LIKE CONCAT('%', #{keyword}, '%')

            OR g.category_id IN

                #{cid}


    )

ORDER BY g.create_time DESC, g.id DESC
LIMIT #{limit}

SELECT g.*, u.account AS publisher_account FROM intangible_goods g LEFT JOIN sys_user u ON u.id = g.publisher_id AND u.is_deleted = 0 WHERE g.is_deleted = 0
AND g.status = #{auditStatus}
ORDER BY g.create_time DESC, g.id ASC
